#define CODEX_CATS 4
#define CODEX_CAT_STRUCTURES   0
#define CODEX_CAT_INFANTRY     1
#define CODEX_CAT_VEHICLES     2
#define CODEX_CAT_AIRCRAFT     3

static const char* const CODEX_CAT_NAME[CODEX_CATS] = {
    "STRUCTURES", "INFANTRY", "VEHICLES", "AIRCRAFT"
};

#define CODEX_HOUSE_GDI 1u
#define CODEX_HOUSE_NOD 2u

/* THE BAR SCALES. One per stat for the WHOLE table, so two entries can be compared
   by eye; computed across every row rather than picked. ROF is ticks BETWEEN shots,
   so its bar is drawn inverted while the printed number stays the source's. */
#define CODEX_MAX_HP     1000
#define CODEX_MAX_DAMAGE 200
#define CODEX_MAX_SPEED  40
#define CODEX_MAX_ROF    200
#define CODEX_MAX_COST   5000

typedef struct {
    const char* code;      /* INI ident; also the pack's mesh key */
    const char* name;      /* the 1995 display name, from conquer.h */
    const char* brief;     /* derived, see the header note */
    int         cat;       /* CODEX_CAT_* */
    unsigned    houses;    /* CODEX_HOUSE_* bit field */
    int         hitpoints; /* STRENGTH */
    int         cost;      /* credits */
    int         speed;     /* MPH; -1 where the family has no speed */
    int         damage;    /* primary weapon damage; -1 unarmed */
    int         rof;       /* ticks between shots; -1 unarmed */
    int         range256;  /* weapon range in leptons, 256 to the cell */
    const char* armour;
    const char* strong;    /* what its warhead beats, by name */
    const char* weak;      /* what beats its armour, by name */
    const char* unlocks;   /* what names it as a prerequisite */
} CodexRow;

